WITH flattened AS (SELECT id, plan, effective_from, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) x AS val), scored AS (SELECT *, DENSE_RANK() OVER (PARTITION BY plan ORDER BY val DESC) AS val_dense_rank, AVG(val) OVER w_hist AS plan_avg_val FROM flattened WINDOW w_hist AS (PARTITION BY plan)), enriched AS (SELECT val_dense_rank, plan_avg_val, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY plan_avg_val DESC) AS plan_avg_val_percent_rank, MAX(val) OVER (PARTITION BY plan) AS plan_max_val, CUME_DIST() OVER (ORDER BY val_dense_rank DESC NULLS LAST) AS val_dense_rank_cume_dist FROM scored WHERE effective_from <= '2023-09-01'), enriched_price_tiers AS (SELECT plan_avg_val, val_dense_rank_cume_dist, RANK() OVER (ORDER BY plan_avg_val DESC NULLS LAST) AS plan_avg_val_rank, RANK() OVER (ORDER BY plan_max_val NULLS LAST) AS plan_max_val_rank, PERCENT_RANK() OVER (ORDER BY val_dense_rank NULLS LAST) AS val_dense_rank_percent_rank FROM enriched), base AS (SELECT *, ROUND(plan_max_val_rank * 1.1, 2) AS adjusted_plan_max_val_rank FROM enriched_price_tiers WHERE plan_avg_val_rank >= 7) SELECT plan_avg_val_rank, plan_max_val_rank, adjusted_plan_max_val_rank, DENSE_RANK() OVER (ORDER BY plan_max_val_rank) AS plan_max_val_rank_dense_rank FROM base;
